            best_overlap = overlap
            best_edges = edges
            best_layer = layer

    if best_layer is None:
        return pd.DataFrame(columns=['step', 'value'])

    exp_events = events[(events['state'] == 'exposed') & (events['after'] == True)]
    total_per_step = exp_events.groupby('step').size().reset_index(name='total')

    hh_events = exp_events[exp_events['partner_id'].notna() & (exp_events['layer'] == best_layer)]
