def compute_indicator(data, config):
    st = data['agent_states'][['run_id', 'agent_id', 'step', 'quarantined']]
    st = st.dropna(subset=['run_id', 'agent_id', 'step']).copy()
    st['step'] = st['step'].to_numpy(dtype='int64')
    st['quarantined'] = st['quarantined'].fillna(False).astype(bool)
    if st.empty:
        return pd.Series(dtype='float64', index=pd.Index([], name='step', dtype='int64'), name='value')
    deg = _degrees(_all_layer_edges(data['contacts']))
    grid = st.merge(deg, on=['run_id', 'step', 'agent_id'], how='left')
    grid['degree'] = grid['degree'].fillna(0.0)
    quar = grid[grid['quarantined']]
    if quar.empty:
        return pd.Series(dtype='float64', index=pd.Index([], name='step', dtype='int64'), name='value')
    g = quar.groupby(['run_id', 'step'])['degree']
    stats = pd.DataFrame({'n': g.size(), 'mean': g.mean(), 'sd': g.std(ddof=1)}).reset_index()
    stats = stats[(stats['n'] >= 2) & (stats['mean'] != 0) & stats['sd'].notna()].copy()
    stats['cv'] = stats['sd'] / stats['mean']
    res = stats.groupby('step')['cv'].mean()
    res.index.names = ['step']
    return res.rename('value')

import numpy as np
import pandas as pd


def _undirected_edges(contacts):
    c = contacts[['run_id', 'step', 'layer', 'agent_id', 'partner_id']]
    c = c.dropna(subset=['run_id', 'step', 'layer', 'agent_id', 'partner_id'])
    a = c['agent_id'].to_numpy(dtype='int64')
    b = c['partner_id'].to_numpy(dtype='int64')
    e = pd.DataFrame({
        'run_id': c['run_id'].to_numpy(),
        'step': c['step'].to_numpy(dtype='int64'),
        'layer': c['layer'].to_numpy(),
        'u': np.minimum(a, b),
        'v': np.maximum(a, b),
    })
    return e.drop_duplicates(subset=['run_id', 'step', 'layer', 'u', 'v'])


def _layer_degrees(edges):
    left = edges[['run_id', 'step', 'layer', 'u']].rename(columns={'u': 'agent_id'})
    right = edges[['run_id', 'step', 'layer', 'v']].rename(columns={'v': 'agent_id'})
    stacked = pd.concat([left, right], ignore_index=True)
    d = stacked.groupby(['run_id', 'step', 'layer', 'agent_id']).size().rename('degree')
    return d.reset_index()


def _fill_cols(df, spec):
    out = df.copy()
    for name, value in spec:
        if name not in out.columns:
            out[name] = value
    return out


def compute_indicator(data, config):
    st = data['agent_states'][['run_id', 'step', 'agent_id', 'quarantined']]
    st = st.dropna(subset=['run_id', 'step', 'agent_id']).copy()
    st['step'] = st['step'].to_numpy(dtype='int64')
    st['quarantined'] = st['quarantined'].fillna(False).astype(bool)
    empty_idx = pd.MultiIndex.from_arrays([np.array([], dtype='int64'), np.array([], dtype='object')], names=['step', 'layer'])
    if st.empty:
        return pd.Series(dtype='float64', index=empty_idx, name='value')
    deg = _layer_degrees(_undirected_edges(data['contacts']))
    if deg.empty:
        return pd.Series(dtype='float64', index=empty_idx, name='value')
    joined = deg.merge(st, on=['run_id', 'step', 'agent_id'], how='inner')
    sums = joined.groupby(['run_id', 'step', 'layer', 'quarantined'])['degree'].sum().reset_index()
    piv = sums.pivot_table(index=['run_id', 'step', 'layer'], columns='quarantined', values='degree', aggfunc='sum').reset_index()
    piv = piv.rename(columns={True: 'sum_q', False: 'sum_n'})
    piv = _fill_cols(piv, [('sum_q', 0.0), ('sum_n', 0.0)])
    piv[['sum_q', 'sum_n']] = piv[['sum_q', 'sum_n']].fillna(0.0)
    cnt = st.groupby(['run_id', 'step', 'quarantined']).size().unstack('quarantined').reset_index()
    cnt = cnt.rename(columns={True: 'cnt_q', False: 'cnt_n'})
    cnt = _fill_cols(cnt, [('cnt_q', 0), ('cnt_n', 0)])
    cnt[['cnt_q', 'cnt_n']] = cnt[['cnt_q', 'cnt_n']].fillna(0)
    work = piv.merge(cnt, on=['run_id', 'step'], how='inner')
    work = work[(work['cnt_q'] > 0) & (work['cnt_n'] > 0)].copy()
    if work.empty:
        return pd.Series(dtype='float64', index=empty_idx, name='value')
    work['mean_q'] = work['sum_q'] / work['cnt_q']
    work['mean_n'] = work['sum_n'] / work['cnt_n']
    work = work[work['mean_n'] > 0].copy()
    if work.empty:
        return pd.Series(dtype='float64', index=empty_idx, name='value')
    work['value'] = work['mean_q'] / work['mean_n']
    res = work.groupby(['step', 'layer'])['value'].mean()
    res.index.names = ['step', 'layer']
    return res.rename('value')

import numpy as np
import pandas as pd


def _all_layer_edges(contacts):
    c = contacts[['run_id', 'step', 'layer', 'agent_id', 'partner_id']]
    c = c.dropna(subset=['run_id', 'step', 'layer', 'agent_id', 'partner_id'])
    a = c['agent_id'].to_numpy(dtype='int64')
    b = c['partner_id'].to_numpy(dtype='int64')
    e = pd.DataFrame({
        'run_id': c['run_id'].to_numpy(),
        'step': c['step'].to_numpy(dtype='int64'),
        'u': np.minimum(a, b),
        'v': np.maximum(a, b),
    })
    return e.drop_duplicates(subset=['run_id', 'step', 'u', 'v'])


def compute_indicator(data, config):
    edges = _all_layer_edges(data['contacts'])
    if edges.empty:
        return pd.Series(dtype='float64', index=pd.Index([], name='step', dtype='int64'), name='value')
    vol = edges.groupby(['run_id', 'step']).size().rename('E').reset_index()
    vol = vol.sort_values(['run_id', 'step']).reset_index(drop=True)
    g = vol.groupby('run_id', sort=False)
    prev_e = g['E'].shift(1)
    prev_step = g['step'].shift(1)
    ok = (prev_step == vol['step'] - 1) & prev_e.notna() & (prev_e > 0)
    keep = ok.to_numpy()
    if not keep.any():
        return pd.Series(dtype='float64', index=pd.Index([], name='step', dtype='int64'), name='value')
    sub = vol.loc[keep, ['run_id', 'step', 'E']].copy()
    sub['prev_E'] = prev_e.to_numpy()[keep]
    sub['value'] = (sub['E'] - sub['prev_E']) / sub['prev_E']
    res = sub.groupby('step')['value'].mean()
    res.index.names = ['step']
    return res.rename('value')

import numpy as np
import pandas as pd


def _flag_transitions(df, col):
    x = df.dropna(subset=['run_id', 'agent_id', 'step']).copy()
    if x.empty:
        return pd.DataFrame(columns=['run_id', 'agent_id', 'step'])
    x['agent_id'] = x['agent_id'].astype('int64')
    x['step'] = x['step'].astype('int64')
    x[col] = x[col].fillna(False).astype(bool)
    x = x.drop_duplicates(subset=['run_id', 'agent_id', 'step']).sort_values(['run_id', 'agent_id', 'step'])
    prev = x.groupby(['run_id', 'agent_id'], sort=False)[col].shift(1)
    cur = x[col].to_numpy(dtype=bool)
    prev_false = (~prev.fillna(False).astype(bool)).to_numpy()
    mask = cur & prev_false
    return x.loc[mask, ['run_id', 'agent_id', 'step']].reset_index(drop=True)


def _empty_frame(col):
    idx = pd.MultiIndex.from_arrays([[] for _ in range(3)], names=['step', 'run_id', 'agent_id'])
    return pd.DataFrame({col: pd.Series(dtype='float64', index=idx)})


def compute_indicator(data, config):
    ast = data['agent_states']
    tr = _flag_transitions(ast[['run_id', 'agent_id', 'step', 'exposed']], 'exposed')
