        return _empty_frame('exposure_step_index')
    first = tr.groupby(['run_id', 'agent_id'], sort=True)['step'].min().rename('exposure_step_index').reset_index()
    first['exposure_step_index'] = first['exposure_step_index'].astype('float64')
    out = first.set_index(['step', 'run_id', 'agent_id'])[['exposure_step_index']].sort_index()
