    trough = grid_n.loc[grid_n.groupby('run_id', sort=True)['n'].idxmin()]
    trough = trough[['run_id', 'step']].rename(columns={'step': 'trough_step'})
    first = tr.groupby(['run_id', 'agent_id'], sort=True)['step'].min().rename('exposure_step').reset_index()
    joined = first.merge(trough, on='run_id', how='inner')
