    ag['_prev_exposed'] = ag.groupby(group_cols, sort=False)['_exposed'].shift(1)
    trans = ag[(ag['_prev_exposed'].notna()) & (~ag['_prev_exposed'].astype(bool)) & (ag['_exposed'])].copy()
    if trans.empty:
        return pd.Series(dtype=float, name='post_trough_exposure_flag')

    if has_run:
        trans['_tstar'] = trans['run_id'].map(troughs)
