def compute_indicator(data, config):
    import pandas as pd
    import numpy as np

    ag = data['agent_states'].copy()
    ev = data['events'].copy()
    co = data['contacts'].copy()

    ag = ag.dropna(subset=['step'])
    ag['step'] = ag['step'].astype(int)
    has_run = 'run_id' in ag.columns
    if has_run:
        ag = ag.dropna(subset=['run_id'])
    ag['_infectious'] = ag['infectious'].fillna(False).astype(bool)

    if has_run:
        inf_counts = ag.groupby(['run_id', 'step'], sort=True)['_infectious'].sum()
        troughs = {}
        for rid, sub in inf_counts.groupby(level=0):
