                continue
            m = sub.min()
            steps = sub[sub == m].index.get_level_values('step')
            if len(steps):
                troughs[rid] = int(steps.min())
    else:
        inf_counts = ag.groupby('step', sort=True)['_infectious'].sum()
        trough = None
        if not inf_counts.empty:
            m = inf_counts.min()
            steps = inf_counts[inf_counts == m].index
            trough = int(steps.min())

    ev = ev.dropna(subset=['step', 'layer'])
    ev['step'] = ev['step'].astype(int)
    if has_run and 'run_id' in ev.columns:
        ev = ev.dropna(subset=['run_id'])
    ev['_is_exposed'] = ev['state'].astype(str).str.lower().eq('exposed') & ev['after'].fillna(False).astype(bool)
    ev_f = ev[ev['_is_exposed']].copy()

    co = co.dropna(subset=['step', 'layer'])
    co['step'] = co['step'].astype(int)
    if has_run and 'run_id' in co.columns:
        co = co.dropna(subset=['run_id'])
    edge_cols = ['run_id', 'step', 'layer', 'agent_id', 'partner_id'] if has_run else ['step', 'layer', 'agent_id', 'partner_id']
    co_edges = co.drop_duplicates(subset=edge_cols)

    if has_run:
        exp_counts = ev_f.groupby(['run_id', 'step', 'layer'], sort=True).size()
        edge_counts = co_edges.groupby(['run_id', 'step', 'layer'], sort=True).size()
    else:
        exp_counts = ev_f.groupby(['step', 'layer'], sort=True).size()
        edge_counts = co_edges.groupby(['step', 'layer'], sort=True).size()

    lam = exp_counts.rename('exposures').to_frame().join(edge_counts.rename('edges'), how='outer')
    lam['exposures'] = lam['exposures'].fillna(0.0)
    lam['edges'] = lam['edges'].fillna(0.0)
    lam = lam[lam['edges'] > 0].copy()
    lam['lambda'] = lam['exposures'] / lam['edges']
    lam = lam.reset_index()
    lam['step'] = lam['step'].astype(int)

    rows = []
    if has_run:
        for rid, sub in lam.groupby('run_id', sort=True):
            t = troughs.get(rid)
            if t is None:
                continue
            for layer, ssub in sub.groupby('layer', sort=True):
                s = ssub.set_index('step')['lambda'].sort_index()
                if t not in s.index:
                    continue
                val_t = s.loc[t]
                if not np.isfinite(val_t) or val_t <= 0:
                    continue
                after = s[s.index > t]
                after = after[np.isfinite(after)]
                if after.empty:
                    continue
                phi = float(after.mean() / val_t)
                if np.isfinite(phi):
                    rows.append((rid, t, layer, phi))
    else:
        if trough is not None:
            for layer, ssub in lam.groupby('layer', sort=True):
                s = ssub.set_index('step')['lambda'].sort_index()
                if trough not in s.index:
                    continue
                val_t = s.loc[trough]
                if not np.isfinite(val_t) or val_t <= 0:
                    continue
                after = s[s.index > trough]
                after = after[np.isfinite(after)]
                if after.empty:
                    continue
                phi = float(after.mean() / val_t)
                if np.isfinite(phi):
                    rows.append((trough, layer, phi))

    if not rows:
        return pd.Series(dtype=float, name='post_trough_incidence_ratio')
    if has_run:
        idx = pd.MultiIndex.from_tuples([(r[0], r[1], r[2]) for r in rows], names=['run_id', 'step', 'layer'])
        return pd.Series([r[3] for r in rows], index=idx, name='post_trough_incidence_ratio')
    idx = pd.MultiIndex.from_tuples([(r[0], r[1]) for r in rows], names=['step', 'layer'])
    return pd.Series([r[2] for r in rows], index=idx, name='post_trough_incidence_ratio')

